#include <stdio.h>
#include <math.h>
typedef struct{float x,y,z;}V;
static V ad(V a,V b){V r={a.x+b.x,a.y+b.y,a.z+b.z};return r;}
static V sb(V a,V b){V r={a.x-b.x,a.y-b.y,a.z-b.z};return r;}
static V ml(V a,float t){V r={a.x*t,a.y*t,a.z*t};return r;}
static float dt(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static V nm(V a){float l=sqrtf(dt(a,a));V r={a.x/l,a.y/l,a.z/l};return r;}
static int sph(V o,V d,V c,float r,float*t,V*p,V*n){
 V oc=sb(o,c);float a=dt(d,d),b=2*dt(oc,d),cc=dt(oc,oc)-r*r,ds=b*b-4*a*cc;
 if(ds<0)return 0;float s=sqrtf(ds),t0=(-b-s)/(2*a),t1=(-b+s)/(2*a);
 if(t0<0.001f){if(t1<0.001f)return 0;*t=t1;}else *t=t0;
 *p=ad(o,ml(d,*t));*n=nm(sb(*p,c));return 1;}
static int pln(V o,V d,float py,float*t,V*p,V*n){
 if(fabsf(d.y)<0.001f)return 0;float tt=(py-o.y)/d.y;if(tt<0.001f)return 0;
 *t=tt;*p=ad(o,ml(d,tt));n->x=0;n->y=1;n->z=0;return 1;}
static V sky(V d){float t=0.5f*(d.y+1);V a={1,1,1},b={0.5f,0.7f,1};return ad(ml(a,1-t),ml(b,t));}
static int sh(V p,V l){float t;V h,n;return sph(p,l,(V){0,0,-5},1,&t,&h,&n);}
static V tr(V o,V d){
 float t;V p,n;V L={0.26311f,0.93894f,-0.22175f};
 if(sph(o,d,(V){0,0,-5},1,&t,&p,&n)){
  float df=dt(n,L);if(df<0)df=0;float s=0.2f+0.8f*df;
  if(sh(ad(p,ml(n,0.001f)),L))s=0.2f;
  V c={s,0.2f*s,0.2f*s};return c;}
 if(pln(o,d,-1.5f,&t,&p,&n)){
  float df=dt(n,L);if(df<0)df=0;float s=0.2f+0.8f*df;
  if(sh(ad(p,ml(n,0.001f)),L))s=0.2f;
  float f=(((int)floorf(p.x)+(int)floorf(p.z))&1)?0.9f:0.39f;
  V c={s*f,s*f,s*f};return c;}
 return sky(d);}
int main(void){
 int W=800,H=600;
 fprintf(stderr,"Creating high-resolution image: %dx%d\n",W,H);
 fprintf(stderr,"This will be downsampled with ffmpeg after rendering\n");
 fprintf(stderr,"Rendering high-resolution image...\n");
 FILE*f=fopen("image.ppm","w");
 fprintf(f,"P3\n%d %d\n255\n",W,H);
 for(int y=0;y<H;y++){
  fprintf(stderr,"\rProgress: %.1f%%",100.0f*y/H);
  for(int x=0;x<W;x++){
   float vy=(300.0f-y)*(2.0f/600.0f);
   float w=(x-400.0f)*(2.6666667f/800.0f);
   V d=nm((V){0,vy,w});
   V c=tr((V){0,0,0},d);
   float r=c.x<0?0:(c.x>1?1:c.x),g=c.y<0?0:(c.y>1?1:c.y),b=c.z<0?0:(c.z>1?1:c.z);
   fprintf(f,"%d %d %d\n",(int)(r*255.99f),(int)(g*255.99f),(int)(b*255.99f));}}
 fclose(f);
 fprintf(stderr,"\nRendering complete\n");
 fprintf(stderr,"Wrote image to %s\n","image.ppm");
 fprintf(stderr,"Done.\n");
 return 0;}
