#include <stdio.h>
#include <math.h>
static int R[600][800],G[600][800],B[600][800];
static double s=255.99;
int main(){
  FILE*fp=fopen("ref.txt","r");
  for(int r=0;r<600;r++)for(int c=0;c<800;c++)fscanf(fp,"%d %d %d",&R[r][c],&G[r][c],&B[r][c]);
  fclose(fp);
  double a=0.00305,cx=0.25,cy=-0.30,cz=-6.80;
  /* sky check */
  int bad=0,tot=0;
  for(int r=0;r<600;r++)for(int c=0;c<800;c++){
    if(B[r][c]!=255||r>260)continue;
    double vy=1.0-2.0*r/600.0;
    double dx0=a*(c-400.0);
    double len=sqrt(dx0*dx0+vy*vy+1.0);
    double dy=vy/len;
    double t=0.5*(dy+1);
    int pr=(int)((1-0.5*t)*s), pg=(int)((1-0.3*t)*s);
    tot++; if(pr!=R[r][c]||pg!=G[r][c])bad++;
  }
  printf("sky: %d/%d mismatch (%.3f%%)\n",bad,tot,100.0*bad/tot);
  /* sphere bbox */
  int minr=9999,maxr=-1,minc=9999,maxc=-1;
  for(int r=0;r<600;r++)for(int c=0;c<800;c++){
    double vy=1.0-2.0*r/600.0;
    double dx0=a*(c-400.0);
    double len=sqrt(dx0*dx0+vy*vy+1.0);
    double dx=dx0/len,dy=vy/len,dz=-1.0/len;
    double ocx=-cx,ocy=-cy,ocz=-cz;
    double b=2*(ocx*dx+ocy*dy+ocz*dz);
    double cc=ocx*ocx+ocy*ocy+ocz*ocz-1;
    double disc=b*b-4*cc;
    if(disc<0)continue;
    double t=(-b-sqrt(disc))/2;
    if(t<0.001)t=(-b+sqrt(disc))/2;
    if(t<0.001)continue;
    if(r<minr)minr=r;if(r>maxr)maxr=r;if(c<minc)minc=c;if(c>maxc)maxc=c;
  }
  printf("sphere bbox rows %d-%d cols %d-%d (ref 270-358, 365-460)\n",minr,maxr,minc,maxc);
  return 0;
}
